import{_ as s,c as i,a as t,aS as a}from"./chunks/framework.BB9D2qGO.js";const l="/assets/%E9%B1%BC1.Cbiqa9gN.jpg",e="/assets/%E9%B1%BC2.Du6HB6wK.jpg",o="/assets/%E9%B1%BC3.BQMlDhqb.jpg",r="/assets/%E9%B1%BC4.BRauGFpp.jpg",c="/assets/%E9%B1%BC5.CP4rY7Cc.jpg",_="/assets/%E9%B1%BC6.DsoRob-3.jpg",p="/assets/%E9%B1%BC7.Cc0RCX8d.jpg",n="/assets/%E9%B1%BC8.DP305m5r.jpg",m="/assets/%E9%B1%BC9.CcovNA5R.jpg",B="/assets/%E9%B1%BC10.Cyg3YuiA.jpg",d="/assets/%E9%B1%BC11.X-h2bSGD.jpg",S=JSON.parse('{"title":"我的鱼缸","description":"","frontmatter":{},"headers":[],"relativePath":"fish/index.md","filePath":"fish/index.md","lastUpdated":1755787482000}'),g={name:"fish/index.md"},h=a('<h1 id="我的鱼缸" tabindex="-1">我的鱼缸 <a class="header-anchor" href="#我的鱼缸" aria-label="Permalink to &quot;我的鱼缸&quot;">​</a></h1><p>想不到吧，我还是一个钓鱼佬</p><h2 id="我的鱼缸里面的鱼" tabindex="-1">我的鱼缸里面的鱼 <a class="header-anchor" href="#我的鱼缸里面的鱼" aria-label="Permalink to &quot;我的鱼缸里面的鱼&quot;">​</a></h2><p>我的鱼缸是80*40的超白白晶缸，貌似二百多吧，不到三百。我喜欢搞水草缸，不喜欢裸缸，反正是缸里面不能啥都没有，起码有些装饰品，水草，石头 之类的东西。前期也是搞的乱七八糟的东西买了一堆，过滤器，射灯，加热棒，水草泥，水草种子，鱼食... 真没少折腾</p><p>结果就是 水草种子一个也没养活，无奈只能买成品的水草。</p><p>鱼的话，我喜欢小型热带鱼，主打一个每样来几只。下面是鱼缸成员清单。</p><ul><li>金鱼。这是我妈在集市上买的，2块钱一条，实话实说，金鱼是真能活，能吃能拉，而且战斗力很强，一口一个小鱼，贼猛。</li><li>孔雀鱼 非常漂亮的热带鱼</li><li>鹦鹉鱼 也是非常的漂亮，又小又猛</li><li>斑马鱼 五颜六色的，也挺好看</li><li>条纹小鲃 又小又猛</li><li>鳑鲏 我感觉挺漂亮的，非常nice</li><li>黑尾大勾 群游之王，很漂亮</li><li>清道夫-金苔鼠鱼、彩虹鲨、黄金鲨 主要是让这家伙清理藻类的</li><li>虾虎鱼 在鱼坑里面逮的，这家伙专吃虾米</li><li>斗鱼 在鱼坑里面逮的，这家伙专吃虾米，放鱼缸2天，虾米快被它吃完了，结果让我把它和乌龟安排在一起了，见它太奶了</li><li>河蚌 买螃蟹送的</li><li>海螺 在鱼坑里面逮的</li><li>黄金泥鳅 清理藻类的</li><li>迷你辣椒蟹 小的很，贼可爱，就是不适合深水，养不长就嗝屁</li><li>乌龟 在深水区也可以存活，会自己跑水面透气，逮小鱼猛的很，像孔雀鱼那种游的慢的，一口一个，12个孔雀鱼，让乌龟给我干死4个</li><li>螃蟹 有将军蟹和相手蟹 大的小的都有，不得不说 螃蟹实在是太猛了 攻守兼备，钳子夹住手是真疼，但是吧，还是没有乌龟猛， 螃蟹对温度和水深太敏感了，放鱼缸里面不行，水太深，而且吃鱼，然后我放小缸里面了，外面温度太高，30分钟不到就给热死了，剩余没有热死的，我 给放大缸里了，大缸里面种的荷花，大的螃蟹竟然顺着越狱了，艹。最后我把乌龟也放大缸里，乌龟把螃蟹给吃了。</li><li>黑壳虾 前前后后买了几百只，有的被鱼吃了，有的被过滤器吸走了，有的怀宝宝了。</li></ul><p><img src="'+l+'" alt=""><img src="'+e+'" alt=""><img src="'+o+'" alt=""><img src="'+r+'" alt=""><img src="'+c+'" alt=""><img src="'+_+'" alt=""><img src="'+p+'" alt=""><img src="'+n+'" alt=""><img src="'+m+'" alt=""><img src="'+B+'" alt=""><img src="'+d+'" alt=""></p>',8),C=[h];function u(f,E,j,x,b,P){return t(),i("div",null,C)}const q=s(g,[["render",u]]);export{S as __pageData,q as default};
